(function(){
  function escRe(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
  function replace(text, find, repl, opt){
    opt=opt||{};
    if(find==null||find==='') return {value:{result:String(text), count:0}};
    var flags='';
    if(opt.ignoreCase) flags+='i';
    var re;
    try{ re=new RegExp(opt.regex?find:escRe(find), flags+(opt.global?'g':'')); }
    catch(e){ return {error:'正则无效: '+e.message}; }
    var result=String(text).replace(re, repl);
    var count = opt.global ? ((String(text).match(re)||[]).length)
                            : (re.test(String(text))?1:0);
    return {value:{result:result, count:count}};
  }
  var API={replace:replace, escRe:escRe};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__SdForge__=API;
})();
